"""Central Strategy Arbiter & Authoritative Risk Governor (Phase 6).

Implements the single decision pipeline:
MarketSnapshot -> S1/S2/S3 Assessments -> Arbiter -> TradeIntent -> RiskGovernor -> Execution.
"""
from __future__ import annotations

import logging
from dataclasses import dataclass, field
from datetime import datetime
from typing import Any

import settings
from engines.strategies import StrategyAssessment

log = logging.getLogger(__name__)


@dataclass
class TradeIntent:
    """Structured proposal generated by the Arbiter for the RiskGovernor to approve/reject."""
    strategy_id: str
    direction: str                     # "LONG" | "SHORT"
    entry_zone: tuple[float, float]
    initial_sl: float
    target_plan: str
    confidence_tier: str
    reason_codes: list[str]
    blocker_codes: list[str]
    snapshot_id: str
    valid_until: datetime
    risk_units: float = 1.0
    approved: bool = False
    rejection_reason: str | None = None


def make_range_gate_decision_record(strategy: str = "S2_VWAP_MOMENTUM", market_state: str = "RANGE") -> dict[str, str]:
    """Generates a deterministic decision record for RANGE_GATE blocks (Phase 8)."""
    return {
        "strategy": strategy,
        "market_state": market_state,
        "decision": "BLOCK",
        "reason": "RANGE_GATE_S2_BLOCKED",
    }


class Arbiter:
    """Compares parallel StrategyAssessments and selects the primary trade intent."""

    def __init__(self):
        self.decision_records: list[dict[str, str]] = []
        self.last_decision_record: dict[str, str] | None = None

    def evaluate(self, assessments: list[StrategyAssessment], market_state: str = "NORMAL") -> tuple[TradeIntent | None, list[StrategyAssessment], str]:
        """Returns (primary_intent, shadow_assessments, no_trade_reason)."""
        eligible = [a for a in assessments if a.eligible and a.direction in ("LONG", "SHORT")]
        if not eligible:
            blockers = []
            for a in assessments:
                blockers.extend(a.blocker_codes)
            reason = "No eligible strategy setups: " + (", ".join(set(blockers)) if blockers else "low score")
            return None, [], reason

        # -------------------------------------------------------------
        # 1. Elimination Gates
        # -------------------------------------------------------------
        ms_upper = (market_state or "").upper()
        survivors = []
        for a in eligible:
            # RANGE_GATE (Phase 8): S2 VWAP Momentum strictly prohibited in RANGE regimes
            if a.strategy_id == "S2_VWAP_MOMENTUM" and "RANGE" in ms_upper:
                rec = make_range_gate_decision_record(strategy=a.strategy_id, market_state=market_state)
                self.last_decision_record = rec
                self.decision_records.append(rec)
                log.info("RANGE_GATE_S2_BLOCKED: strategy=%s, market_state=%s, decision=BLOCK, reason=RANGE_GATE_S2_BLOCKED", a.strategy_id, ms_upper)
                continue

            # S3 Trend Override Veto: Counter-trend reversals forbidden in trending markets
            if a.strategy_id == "S3_LIQUIDITY_REVERSAL":
                if ("TREND-DOWN" in ms_upper or "DOWN" in ms_upper or "BEAR" in ms_upper) and a.direction == "LONG":
                    log.warning("Arbiter vetoed S3 LONG: COUNTER_TREND_REVERSAL_FORBIDDEN_IN_TREND_DOWN")
                    continue
                if ("TREND-UP" in ms_upper or "UP" in ms_upper or "BULL" in ms_upper) and a.direction == "SHORT":
                    log.warning("Arbiter vetoed S3 SHORT: COUNTER_TREND_REVERSAL_FORBIDDEN_IN_TREND_UP")
                    continue
            # Risk-to-reward ratio minimum 1.5
            if a.risk_reward_ratio < 1.5:
                continue
            # S2 VWAP Momentum requires proximity to VWAP (<1.8 ATR)
            if a.strategy_id == "S2_VWAP_MOMENTUM" and a.normalized_extension > 1.8:
                continue
            # Extreme extension penalty (>3.0 ATR from VWAP is climax/exhaustion)
            if a.normalized_extension > 3.0:
                continue
            survivors.append(a)

        if not survivors:
            if any(a.strategy_id == "S2_VWAP_MOMENTUM" for a in eligible) and "RANGE" in ms_upper:
                return None, [], "RANGE_GATE_S2_BLOCKED"
            return None, [], "All eligible setups eliminated by R:R (<1.5) or over-extension gates"

        # -------------------------------------------------------------
        # 2. Strategy Conflict Resolution (Section 34 requirement)
        # -------------------------------------------------------------
        longs = [a for a in survivors if a.direction == "LONG"]
        shorts = [a for a in survivors if a.direction == "SHORT"]

        if longs and shorts:
            # Severe conflict: e.g. S1/S2 Long vs S3 Short
            # Unless one has overwhelming confidence (score diff >= 25), declare NO_TRADE!
            best_long = max(longs, key=lambda a: a.setup_score)
            best_short = max(shorts, key=lambda a: a.setup_score)
            score_diff = abs(best_long.setup_score - best_short.setup_score)
            if score_diff < 25:
                log.warning("Arbiter detected unresolved strategy conflict: Long (%s: %d) vs Short (%s: %d)",
                            best_long.strategy_id, best_long.setup_score, best_short.strategy_id, best_short.setup_score)
                return None, survivors, f"Unresolved strategy conflict: {best_long.strategy_id} LONG vs {best_short.strategy_id} SHORT"

        # -------------------------------------------------------------
        # 3. Composite Score Ranking
        # -------------------------------------------------------------
        def composite_score(a: StrategyAssessment) -> float:
            exp_factor = min(max(a.empirical_expectancy, 0.0), 1.0) * 100.0
            return (0.35 * a.setup_score) + (0.25 * a.regime_fit_score) + (0.20 * a.structure_score) + (0.20 * exp_factor)

        ranked = sorted(survivors, key=composite_score, reverse=True)
        primary = ranked[0]
        shadows = ranked[1:]

        intent = TradeIntent(
            strategy_id=primary.strategy_id,
            direction=primary.direction,
            entry_zone=primary.entry_zone,
            initial_sl=primary.initial_sl,
            target_plan=primary.management_plan,
            confidence_tier=primary.confidence_tier,
            reason_codes=list(primary.reason_codes),
            blocker_codes=list(primary.blocker_codes),
            snapshot_id=primary.snapshot_id,
            valid_until=primary.valid_until,
            risk_units=1.0,
        )

        return intent, shadows, ""


class RiskGovernor:
    """Authoritative risk governor that validates and approves/rejects TradeIntent."""

    def __init__(
        self,
        max_trades_per_day: int = 2,
        max_trades_per_dir: int = 1,
        profit_lock_r: float = 2.0,
        consecutive_loss_limit: int = 2,
    ):
        self.max_trades_per_day = max_trades_per_day
        self.max_trades_per_dir = max_trades_per_dir
        self.profit_lock_r = profit_lock_r
        self.consecutive_loss_limit = consecutive_loss_limit
        self.decision_records: list[dict[str, str]] = []
        self.last_decision_record: dict[str, str] | None = None

    def validate_intent(
        self,
        intent: TradeIntent,
        current_time: datetime,
        day_total_r: float = 0.0,
        trades_today: int = 0,
        trades_in_dir: int = 0,
        consecutive_losses: int = 0,
        is_blind: bool = False,
        is_event_day: bool = False,
        short_has_strong_confluence: bool = False,
        short_score: int = 90,
        market_state: str = "NORMAL",
    ) -> tuple[bool, str, float]:
        """Returns (approved: bool, reason: str, final_risk_units: float)."""

        # 1. Blindness check
        if is_blind:
            return False, "CANDLE_ENGINE_BLIND (Halt all new entries)", 0.0

        # RANGE_GATE check (Phase 8): Authoritative risk check blocking S2 in RANGE
        if intent.strategy_id == "S2_VWAP_MOMENTUM" and "RANGE" in (market_state or "").upper():
            rec = make_range_gate_decision_record(strategy=intent.strategy_id, market_state=market_state)
            self.last_decision_record = rec
            self.decision_records.append(rec)
            return False, "RANGE_GATE_S2_BLOCKED", 0.0

        # 2. Time cutoff: NO entries after 14:30 IST
        if current_time.time() >= settings.LAST_ENTRY_TIME:
            return False, f"TIME_CUTOFF (After {settings.LAST_ENTRY_TIME.strftime('%H:%M')} IST)", 0.0

        # 3. Scheduled event day check
        if is_event_day:
            return False, "EVENT_DAY_RESTRICTION (Macro event in window)", 0.0

        # 4. Profit lock check (+2.0R banked)
        if day_total_r >= self.profit_lock_r:
            return False, f"PROFIT_LOCK_SHUTDOWN (Day total reaches +{day_total_r:.2f}R >= +{self.profit_lock_r:.1f}R)", 0.0

        # 5. Consecutive loss circuit breaker (2 full losses)
        if consecutive_losses >= self.consecutive_loss_limit:
            return False, f"CONSECUTIVE_LOSS_HALT ({consecutive_losses} consecutive losses)", 0.0

        # 6. Daily trade caps
        if trades_today >= self.max_trades_per_day:
            return False, f"MAX_DAILY_TRADES_REACHED ({trades_today}/{self.max_trades_per_day})", 0.0

        if trades_in_dir >= self.max_trades_per_dir:
            return False, f"MAX_DIRECTION_TRADES_REACHED ({trades_in_dir}/{self.max_trades_per_dir})", 0.0

        # 7. Short Gating Check
        final_risk = 1.0
        if intent.direction == "SHORT":
            if short_score < 90 or not short_has_strong_confluence:
                return False, f"SHORT_GATE_REJECT (Score {short_score} < 90 or missing STRONG level confluence)", 0.0
            # Gated short: scaled to 0.5R risk
            final_risk = 0.5
            intent.reason_codes.append("GATED-SHORT allocation (0.5R risk)")

        intent.risk_units = final_risk
        intent.approved = True
        return True, "APPROVED", final_risk
